node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
const code=(s)=>s.replace(/\/\*[\s\S]*?\*\//g,"").replace(/^\s*\/\/.*$/gm,"")
const L=rd("app/(main)/circles/[slug]/(circle)/layout.tsx")
if(L===null)fail("the circle detail shell is gone")
const lc=code(L)
if(!/\{\s*canEnter\s*\?/.test(lc))fail("the circle shell no longer branches on canEnter: a Circle the viewer may not enter renders as a Circle with ZERO MEMBERS and no reason, which is the defect this row closed")
if(!/<CircleLocked[\s/>]/.test(lc))fail("the shell no longer mounts CircleLocked in place of the tab bodies")
if(!/\{\s*circle\s*,\s*members\s*,\s*theme\s*,\s*canEnter\s*,\s*entryReason\s*\}/.test(lc))fail("the shell stopped taking canEnter and entryReason off the shell, which is exactly how this defect shipped: every consumer destructured around them")
const D=rd("lib/circles/locked-door.ts")
if(D===null)fail("the door copy module is gone")
const dc=code(D)
if(/\bdefault\s*:/.test(dc))fail("circleDoor grew a default arm: a new access mode would silently inherit the sentence of a different mode instead of failing the build")
const REASONS=["signed-out","membership-only","paid","space-members-only","invite-only","closed"]
for(const r of REASONS){if(!new RegExp("case ."+r+".:").test(dc))fail("circleDoor has no arm for the "+r+" refusal, so that viewer gets no sentence")}
if(!/\/memberships/.test(dc))fail("the door module no longer builds a Space memberships href, so a paid wall has nowhere to send the reader")
const armOf=(r)=>{const i=dc.indexOf("case ."+r);const m=new RegExp("case ."+r+".:").exec(dc);if(!m)return null;const start=m.index;let end=dc.length;for(const o of REASONS){const mm=new RegExp("case ."+o+".:").exec(dc);if(mm&&mm.index>start&&mm.index<end)end=mm.index}return dc.slice(start,end)}
for(const r of ["membership-only","paid"]){const arm=armOf(r);if(!arm)fail("could not isolate the "+r+" arm, so this check cannot measure anything");if(!/plans/.test(arm))fail("the "+r+" door stopped sending the reader to the Space memberships tab, which is the one surface that lists the tiers and takes the money")}
for(const r of ["invite-only","closed"]){const arm=armOf(r);if(!arm)fail("could not isolate the "+r+" arm");if(/plans/.test(arm))fail("the "+r+" door now offers a memberships link, but buying a membership does not open an invite-only or host-added circle: that is a door that refuses at the end of it")}
const S=rd("lib/circles/store.ts")
if(S===null)fail("the circle store is gone")
const sc=code(S)
if(!/canEnter,\s*entryReason,/.test(sc))fail("loadCircleShell computes the refusal reason and no longer RETURNS it, so the door has nothing to say (the declaration alone is not the wiring)")
if(!/canJoinCircle\(/.test(sc))fail("the reason is no longer resolved from canJoinCircle, so the UI and the join action can disagree about why someone is outside")
console.log("ok")'
